import json, os
D = os.path.join(os.path.dirname(__file__), "..", "data")

def L(n, level, title, hu, role, grammar, words, phrases):
    uid = f"en-u{n}"
    items = [{"id": f"{uid}-w{i+1}", "k": "w", "it": a, "hu": b} for i, (a, b) in enumerate(words)]
    items += [{"id": f"{uid}-s{i+1}", "k": "s", "it": a, "hu": b} for i, (a, b) in enumerate(phrases)]
    return {"id": uid, "level": level, "track": "gen", "title": title, "hu": hu, "role": role,
            "grammar": [{"h": h, "p": p} for h, p in grammar], "items": items}

