def main():
    p = os.path.join(D, "en.json")
    d = json.load(open(p, encoding="utf-8"))
    units = [u for u in d["units"] if u["id"] not in {x["id"] for x in NEW}]
    gen = [u for u in units if u["track"] == "gen"] + NEW
    order = {"A1": 0, "A2": 1, "B1": 2, "B2": 3, "C1": 4}
    gen.sort(key=lambda u: (order[u["level"]], int(u["id"].split("u")[1])))
    rest = [u for u in units if u["track"] != "gen"]
    d["units"] = gen + rest
    json.dump(d, open(p, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    print("angol általános ág:", len(gen), "lecke; összesen", len(d["units"]), "lecke,", sum(len(u["items"]) for u in d["units"]), "elem")


if __name__ == "__main__":
    main()
